// Nunca deixa $input vazio quebrar o node (SELECT pode nao retornar linha
// nenhuma se a chave "mercadolivre_cookie" nao existir na tabela config).
// O valor do cookie NUNCA e exposto no resultado -- so usamos internamente.

const items = $input.all();
const row = items.length > 0 ? items[0].json : null;
const cookie = row && row.valor ? String(row.valor).trim() : '';

return [{ json: { cookieValido: !!cookie } }];

// Resumo claro de execucao abortada -- nenhuma oferta foi tocada.
console.log('[MONITORAMENTO DE PRECO] Cookie nao configurado; nenhuma oferta foi alterada.');

return [{
  json: {
    status: 'abortado',
    motivo: 'Cookie do Mercado Livre nao configurado (tabela config, chave=mercadolivre_cookie). Nenhuma oferta foi alterada.',
    executadoEm: new Date().toISOString(),
  }
}];

const stats = $getWorkflowStaticData('global');
stats.verificados = 0;
stats.precosAtualizados = 0;
stats.semAlteracao = 0;
stats.indisponiveis = 0;
stats.falhasTemporarias = 0;
stats.revisoesManuais = 0;
stats.alertasAtingidos = 0;
stats.detalhes = [];
return $input.all();

const stats = $getWorkflowStaticData('global');
return [{ json: {
  verificadas: stats.verificados || 0,
  atualizadas: stats.precosAtualizados || 0,
  sem_alteracao: stats.semAlteracao || 0,
  indisponiveis: stats.indisponiveis || 0,
  falhas_temporarias: stats.falhasTemporarias || 0,
  revisoes_manuais: stats.revisoesManuais || 0,
  alertas_atingidos: stats.alertasAtingidos || 0,
  detalhes: stats.detalhes || [],
  parser: 'n8n-v3-seguro',
  executado_em: new Date().toISOString(),
} }];

// MONITORAMENTO V3: modo "falhar fechado".
// Nunca procura preço no HTML inteiro. Só aceita valores ligados ao produto por
// JSON-LD/metadados e pelo bloco principal da página, com confirmação independente.
// A requisição HTTP devolve o HTML; os dados da oferta vêm do loop.
const httpResponse = $input.first().json;
const originalOffer = $('LOOP PRODUTOS').item.json;
const input = { ...originalOffer, ...httpResponse };
const base = {
  offer_id: input.offer_id,
  external_product_id: input.external_product_id || '',
  public_url: input.public_url,
  productTitle: input.product_title || '',
  precoAntigo: Number(input.current_price || 0),
  precoOriginalAntigo: input.original_price === null || input.original_price === undefined ? null : Number(input.original_price),
  parserVersion: 'n8n-v3-seguro',
  httpStatus: Number(input.statusCode || input.status || 200),
};

function cleanText(value) {
  return String(value || '').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
}
function decodeHtml(value) {
  return cleanText(String(value || '')
    .replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>'));
}
function normalize(value) {
  return decodeHtml(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function numberFromMoney(value) {
  const text = cleanText(value).replace(/R\$|\s/g, '');
  if (!text) return null;
  if (/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(text)) return Number(text.replace(/\./g, '').replace(',', '.'));
  if (/^\d+(,\d{1,2})$/.test(text)) return Number(text.replace(',', '.'));
  if (/^\d+(\.\d{1,2})$/.test(text)) return Number(text);
  if (/^\d+$/.test(text)) return Number(text);
  return null;
}
function validPrice(price) {
  return Number.isFinite(price) && price > 0 && price < 1000000;
}
function htmlTitle(html) {
  const h1 = html.match(/<h1[^>]*class="[^"]*(?:ui-pdp-title|ui-pdp-container__title)[^"]*"[^>]*>([\s\S]{0,1000}?)<\/h1>/i);
  const og = html.match(/<meta[^>]+(?:property|name)="og:title"[^>]+content="([^"]+)"/i) || html.match(/<meta[^>]+content="([^"]+)"[^>]+(?:property|name)="og:title"/i);
  return decodeHtml(h1 ? h1[1].replace(/<[^>]+>/g, ' ') : (og ? og[1] : ''));
}
function titleMatches(expected, found) {
  const stop = new Set(['de','da','do','das','dos','para','com','sem','em','e','a','o','um','uma','no','na','por','ml','mercado','livre']);
  const tokens = (text) => normalize(text).split(/[^a-z0-9]+/).filter(t => t.length >= 3 && !stop.has(t));
  const a = [...new Set(tokens(expected))];
  const b = new Set(tokens(found));
  if (a.length < 2 || b.size < 2) return false;
  const same = a.filter(token => b.has(token)).length;
  return same >= 2 && same / Math.min(a.length, b.size) >= 0.30;
}
function collectJsonLd(html) {
  const products = [];
  const scripts = html.match(/<script[^>]+type="application\/ld\+json"[^>]*>[\s\S]*?<\/script>/gi) || [];
  const walk = (entry) => {
    if (!entry || typeof entry !== 'object') return;
    if (Array.isArray(entry)) { entry.forEach(walk); return; }
    const type = Array.isArray(entry['@type']) ? entry['@type'].join(' ') : entry['@type'];
    if (/product/i.test(String(type || ''))) {
      const offers = Array.isArray(entry.offers) ? entry.offers : [entry.offers];
      for (const offer of offers.filter(Boolean)) {
        const price = numberFromMoney(offer.price ?? offer.lowPrice);
        if (validPrice(price)) products.push({ price, title: cleanText(entry.name), source: 'json_ld_product_offer' });
      }
    }
    Object.values(entry).forEach(walk);
  };
  for (const script of scripts) {
    const text = script.replace(/^.*?>/s, '').replace(/<\/script>$/i, '').trim();
    try { walk(JSON.parse(text)); } catch (_) {}
  }
  return products;
}
function metaPrice(html) {
  const patterns = [
    /<meta[^>]+(?:itemprop|property|name)="(?:price|product:price:amount)"[^>]+content="([^"]+)"/i,
    /<meta[^>]+content="([^"]+)"[^>]+(?:itemprop|property|name)="(?:price|product:price:amount)"/i,
  ];
  for (const pattern of patterns) {
    const hit = html.match(pattern);
    const price = hit && numberFromMoney(hit[1]);
    if (validPrice(price)) return price;
  }
  return null;
}
function domMainPrice(html) {
  // O componente tem spans aninhados; pegar até o primeiro </span> cortava o preço.
  // Recortamos apenas a área imediatamente após o contêiner de preço principal.
  const anchorIndex = html.search(/<(?:div|span)[^>]*class="[^"]*(?:ui-pdp-price__second-line|ui-pdp-price)[^"]*"[^>]*>/i);
  if (anchorIndex < 0) return null;
  const block = html.slice(anchorIndex, anchorIndex + 8000);
  const visible = decodeHtml(block.replace(/<[^>]+>/g, ' '));
  // Intervalos, parcelas e mensalidades não representam um preço único confiável.
  if (/R\$\s*[\d.,]+\s*(?:-|a|até)\s*R\$/i.test(visible) || /(?:x\s*R\$|parcela|mensal)/i.test(visible)) return null;
  const fraction = block.match(/andes-money-amount__fraction[^>]*>([\d.]+)/i);
  const cents = block.match(/andes-money-amount__cents[^>]*>(\d{1,2})/i);
  if (fraction) {
    const composed = `${fraction[1].replace(/\./g, '')}${cents ? `,${cents[1]}` : ''}`;
    const price = numberFromMoney(composed);
    if (validPrice(price)) return price;
  }
  const money = visible.match(/R\$\s*([\d.]+(?:,\d{1,2})?)/i);
  const price = money && numberFromMoney(money[1]);
  return validPrice(price) ? price : null;
}
function domPreviousPrice(html) {
  const previous = html.match(/<(?:s|span)[^>]*class="[^"]*(?:previous|old-price|original-price)[^"]*"[^>]*>[\s\S]{0,800}?<\/(?:s|span)>/i);
  if (!previous) return null;
  const text = decodeHtml(previous[0].replace(/<[^>]+>/g, ' '));
  const money = text.match(/R\$\s*([\d.]+(?:,\d{1,2})?)/i);
  const price = money && numberFromMoney(money[1]);
  return validPrice(price) ? price : null;
}
function result(overrides) { return [{ json: { ...base, ...overrides } }]; }

const html = String(input.data || input.body || input.html || '');
if (!html || html.length < 1000) return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', motivo: 'HTML vazio ou incompleto' });
if (/captcha|robot|access denied|forbidden|unusual traffic/i.test(html)) return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', motivo: 'Página bloqueada, CAPTCHA ou acesso negado' });

const pageTitle = htmlTitle(html);
const jsonProducts = collectJsonLd(html);
const jsonMatch = jsonProducts.find(entry => titleMatches(base.productTitle, entry.title));
const meta = metaPrice(html);
const dom = domMainPrice(html);
const sources = [];
if (jsonMatch) sources.push({ price: jsonMatch.price, source: jsonMatch.source });
if (meta) sources.push({ price: meta, source: 'meta_product_price' });
if (dom) sources.push({ price: dom, source: 'dom_main_price' });

if (!pageTitle || !titleMatches(base.productTitle, pageTitle)) {
  return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', pageTitle, motivo: 'Título da página não confirmou a oferta monitorada' });
}
const agreeing = [];
for (let i = 0; i < sources.length; i++) {
  for (let k = i + 1; k < sources.length; k++) {
    if (Math.abs(sources[i].price - sources[k].price) < 0.011) agreeing.push({ price: sources[i].price, source: `${sources[i].source}+${sources[k].source}` });
  }
}
// Um valor diretamente no bloco principal de preço também é aceito quando o título
// da página já confirmou a identidade do produto. Não existe fallback global.
if (!agreeing.length && dom) agreeing.push({ price: dom, source: 'dom_main_price+title_confirmed' });
if (!agreeing.length) {
  return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', pageTitle, motivo: `Preço sem confirmação independente (${sources.map(s => `${s.source}:${s.price}`).join(', ') || 'nenhuma fonte confiável'})` });
}
const precoNovo = agreeing[0].price;
if (!validPrice(precoNovo)) return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', pageTitle, motivo: 'Preço confirmado é inválido' });
if (base.precoAntigo > 0 && (precoNovo / base.precoAntigo > 5 || base.precoAntigo / precoNovo > 5)) {
  return result({ rota: 'falha_temporaria', outcome: 'revisao_manual', pageTitle, detectedCurrentPrice: precoNovo, motivo: `Variação extrema bloqueada: salvo=${base.precoAntigo}, detectado=${precoNovo}` });
}

const previousDom = domPreviousPrice(html);
let precoOriginalNovo = previousDom && previousDom > precoNovo ? previousDom : null;
if (!precoOriginalNovo && base.precoOriginalAntigo && base.precoOriginalAntigo > precoNovo) precoOriginalNovo = base.precoOriginalAntigo;
const discountPercentNovo = precoOriginalNovo && precoOriginalNovo > precoNovo
  ? Number((((precoOriginalNovo - precoNovo) / precoOriginalNovo) * 100).toFixed(2))
  : 0;
const mudou = Math.abs(precoNovo - base.precoAntigo) >= 0.01 || Math.abs((precoOriginalNovo || 0) - (base.precoOriginalAntigo || 0)) >= 0.01;

return result({
  rota: mudou ? 'preco_mudou' : 'sem_alteracao',
  outcome: mudou ? 'updated' : 'unchanged',
  pageTitle,
  precoNovo,
  precoOriginalNovo,
  discountPercentNovo,
  detectedCurrentPrice: precoNovo,
  priceSource: agreeing[0].source,
  motivo: null,
});

