const stats = $getWorkflowStaticData('global');
const p = $('PROCESSA RESPOSTA').item.json;
stats.verificados = (stats.verificados || 0) + 1;
stats.precosAtualizados = (stats.precosAtualizados || 0) + 1;
stats.alertasAtingidos = (stats.alertasAtingidos || 0) + Number($json.alertas_atingidos || 0);
stats.detalhes = [...(stats.detalhes || []), { produto: p.productTitle, offer_id: p.offer_id, resultado: 'Preço atualizado', salvo: p.precoAntigo, detectado: p.precoNovo, fonte: p.priceSource }].slice(-25);
return $input.all();

const stats = $getWorkflowStaticData('global');
const p = $('PROCESSA RESPOSTA').item.json;
stats.verificados = (stats.verificados || 0) + 1;
stats.semAlteracao = (stats.semAlteracao || 0) + 1;
stats.detalhes = [...(stats.detalhes || []), { produto: p.productTitle, offer_id: p.offer_id, resultado: 'Sem alteração', valor: p.precoNovo, fonte: p.priceSource }].slice(-25);
return $input.all();

const stats = $getWorkflowStaticData('global');
const p = $('PROCESSA RESPOSTA').item.json;
stats.verificados = (stats.verificados || 0) + 1;
stats.indisponiveis = (stats.indisponiveis || 0) + 1;
stats.detalhes = [...(stats.detalhes || []), { produto: p.productTitle, offer_id: p.offer_id, resultado: 'Indisponível', motivo: p.motivo }].slice(-25);
return $input.all();

const stats = $getWorkflowStaticData('global');
const p = $('PROCESSA RESPOSTA').item.json;
stats.verificados = (stats.verificados || 0) + 1;
stats.falhasTemporarias = (stats.falhasTemporarias || 0) + 1;
if (p.outcome === 'revisao_manual') stats.revisoesManuais = (stats.revisoesManuais || 0) + 1;
stats.detalhes = [...(stats.detalhes || []), { produto: p.productTitle, offer_id: p.offer_id, resultado: p.outcome === 'revisao_manual' ? 'Revisão manual' : 'Falha temporária', motivo: p.motivo, detectado: p.detectedCurrentPrice || null }].slice(-25);
return $input.all();
